#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> vec1 = {1, 2, 3, 4, 2, 3, 4, 5};
    std::vector<int> vec2 = {2, 3};
    auto pred = [](int a, int b) { return a == b; };
    auto it = std::find_end(vec1.begin(), vec1.end(), vec2.begin(), vec2.end(), pred);
    if (it != vec1.end()) {
        std::cout << "Found sequence ending at position: " << std::distance(vec1.begin(), it) << std::endl;
    } else {
        std::cout << "Sequence not found" << std::endl;
    }
    return 0;
}
